//! Data folders written by released versions open with every record, file and setting they held. Each fixture under
//! `tests/fixtures/data-<version>/` was written by that version's own code (boards, generated and uploaded pictures, a
//! starred picture, one in the trash, a workflow, a comic, the canvas, the screen state, a failed job, two models) and
//! must never be regenerated by a later version. The copy is opened in another folder, as after the user moved it.
use super::common::*;
use novira_core::types::*;
use novira_core::{Backend, BackendConfig, Settings};
use std::path::Path;
use std::sync::Arc;

fn copy_dir(from: &Path, to: &Path) {
    std::fs::create_dir_all(to).unwrap();
    for entry in std::fs::read_dir(from).unwrap() {
        let entry = entry.unwrap();
        let target = to.join(entry.file_name());
        if entry.file_type().unwrap().is_dir() {
            copy_dir(&entry.path(), &target);
        } else {
            std::fs::copy(entry.path(), target).unwrap();
        }
    }
}

fn open_copy(version: &str, dir: &Path) -> Backend {
    let fixture =
        Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("tests/fixtures/data-{version}"));
    copy_dir(&fixture, dir);
    let settings = Settings::load(dir).unwrap();
    Backend::open_with_engine(
        BackendConfig {
            data_dir: dir.to_path_buf(),
            image_url_base: BASE.into(),
            settings,
        },
        Arc::new(FakeEngine::default()),
    )
    .unwrap()
}

/// The name of the one picture in a fixture's `trash/` folder.
fn trashed_name(dir: &Path) -> String {
    std::fs::read_dir(dir.join("trash"))
        .unwrap()
        .map(|e| e.unwrap().file_name().into_string().unwrap())
        .find(|n| n.ends_with(".png"))
        .unwrap()
}

/// Checks a copy of a fixture written by `make_fixture.rs` in the version named.
async fn opens_with_everything_it_held(version: &str) {
    let dir = tempfile::tempdir().unwrap();
    let backend = open_copy(version, dir.path());

    let settings = Settings::load(dir.path()).unwrap();
    assert!(!settings.civitai_lookup);
    assert!(settings.low_memory_mode);
    assert_eq!(settings.comfyui_args, vec!["--fast".to_string()]);
    assert_eq!(settings.comfyui_start_timeout_secs, 300);

    let boot = backend.bootstrap();
    let mut boards: Vec<&str> = boot.boards.iter().map(|b| b.name.as_str()).collect();
    boards.sort_unstable();
    assert_eq!(boards, vec!["Portraits", "Scenery"]);
    let board = |name: &str| {
        boot.boards
            .iter()
            .find(|b| b.name == name)
            .map(|b| b.id.clone())
    };
    assert_eq!(boot.images.len(), 3);
    let in_board = |id: Option<String>| boot.images.iter().find(|i| i.board_id == id).unwrap();
    let starred = in_board(board("Portraits"));
    assert!(starred.starred);
    assert_eq!(
        starred.metadata.as_ref().unwrap().positive_prompt,
        "a cute girl, smile"
    );
    let uncategorized = in_board(None);
    assert!(!uncategorized.starred);
    assert_eq!(
        uncategorized.metadata.as_ref().unwrap().positive_prompt,
        "a cute girl, smile"
    );
    let uploaded = in_board(board("Scenery"));
    assert_eq!((uploaded.width, uploaded.height), (16, 12));
    for image in &boot.images {
        assert!(
            backend.read_image("full", &image.name).is_some(),
            "{}",
            image.name
        );
        assert!(
            backend.read_image("thumb", &image.name).is_some(),
            "{}",
            image.name
        );
    }

    let wf = &boot.workflows[..];
    assert_eq!(wf.len(), 1);
    assert_eq!(
        (wf[0].name.as_str(), wf[0].tags.clone()),
        ("Old workflow", vec!["kept".to_string()])
    );
    assert_eq!(wf[0].graph, serde_json::json!({ "nodes": [1, 2] }));

    let comics = backend.list_comics().unwrap();
    assert_eq!(comics.len(), 1);
    assert_eq!(comics[0].document["title"], "First comic");
    assert_eq!(
        backend.load_canvas().unwrap().as_deref(),
        Some(r#"{"version":1,"entities":[]}"#)
    );
    let ui = backend.adopt_ui_state(None).unwrap().unwrap();
    assert!(ui.contains(r#""novira.theme":"light""#), "{ui}");

    // The models now point into the moved folder and keep their keys, so the saved jobs still name them.
    assert_eq!(boot.models.len(), 2);
    for m in &boot.models {
        assert!(Path::new(&m.path).starts_with(dir.path()), "{}", m.path);
    }
    let main = boot
        .models
        .iter()
        .find(|m| m.kind == ModelType::Main)
        .unwrap();
    let queue = backend.queue_snapshot().items;
    assert_eq!(
        queue.iter().map(|q| q.status).collect::<Vec<_>>(),
        vec![
            QueueItemStatus::Completed,
            QueueItemStatus::Completed,
            QueueItemStatus::Failed
        ]
    );
    assert!(queue.iter().all(|q| q.params.model_key == main.key));

    // The picture in the trash comes back with its file.
    let trashed = trashed_name(dir.path());
    let back = backend
        .restore_images(std::slice::from_ref(&trashed))
        .unwrap();
    assert_eq!(back.len(), 1);
    assert!(backend.read_image("full", &trashed).is_some());

    // The old data still works: a job on the old model key runs and lands next to the old pictures.
    tokio::spawn(backend.clone().run_worker());
    backend
        .enqueue(request(&main.key, "after the update", 1))
        .unwrap();
    wait_until(|| statuses(&backend).last() == Some(&QueueItemStatus::Completed)).await;
    assert_eq!(backend.bootstrap().images.len(), 5);
    backend.shutdown();
}

#[tokio::test]
async fn a_data_folder_of_v0_3_0_opens_with_everything_it_held() {
    opens_with_everything_it_held("v0.3.0").await;
}
